import{_ as s,o as e,c as a,a2 as n}from"./chunks/framework.CvydjLy7.js";const k=JSON.parse('{"title":"9.10 Testcontainers 2.0：一次比 Boot 4 更彻底的模块拆分","description":"","frontmatter":{"title":"9.10 Testcontainers 2.0：一次比 Boot 4 更彻底的模块拆分"},"headers":[{"level":3,"title":"变化一：数据库容器全部移出了 core","slug":"变化一-数据库容器全部移出了-core","link":"#变化一-数据库容器全部移出了-core","children":[]},{"level":3,"title":"变化二：坐标名加了前缀（和 1.x 相反）","slug":"变化二-坐标名加了前缀-和-1-x-相反","link":"#变化二-坐标名加了前缀-和-1-x-相反","children":[]},{"level":3,"title":"变化三：包名从 containers 搬到了各自的技术栈下","slug":"变化三-包名从-containers-搬到了各自的技术栈下","link":"#变化三-包名从-containers-搬到了各自的技术栈下","children":[]},{"level":3,"title":"变化四：去掉了自引用的泛型参数","slug":"变化四-去掉了自引用的泛型参数","link":"#变化四-去掉了自引用的泛型参数","children":[]},{"level":3,"title":"怎么快速判断一个坐标/包名到底改没改","slug":"怎么快速判断一个坐标-包名到底改没改","link":"#怎么快速判断一个坐标-包名到底改没改","children":[]}],"relativePath":"ch09/10.md","filePath":"ch09/10.md","lastUpdated":1789497795000}'),i={name:"ch09/10.md"};function o(r,t,d,l,c,p){return e(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="_9-10-testcontainers-2-0-一次比-boot-4-更彻底的模块拆分" tabindex="-1">9.10 Testcontainers 2.0：一次比 Boot 4 更彻底的模块拆分 <a class="header-anchor" href="#_9-10-testcontainers-2-0-一次比-boot-4-更彻底的模块拆分" aria-label="Permalink to &quot;9.10 Testcontainers 2.0：一次比 Boot 4 更彻底的模块拆分&quot;">​</a></h1><p>Boot 4.1.1 管理的 Testcontainers 版本是 <strong>2.0.5</strong>。这是一个大版本跨越（1.21.x 直接跳到 2.0），变化集中在模块与包名上，而且<strong>有些地方跟直觉相反</strong>。</p><h3 id="变化一-数据库容器全部移出了-core" tabindex="-1">变化一：数据库容器全部移出了 core <a class="header-anchor" href="#变化一-数据库容器全部移出了-core" aria-label="Permalink to &quot;变化一：数据库容器全部移出了 core&quot;">​</a></h3><p>1.x 时代，<code>org.testcontainers:testcontainers</code> 这一个 jar 里什么都有：<code>GenericContainer</code> 和 <code>MySQLContainer</code>、<code>PostgreSQLContainer</code> 是邻居。2.0 之后，core 里只剩与具体中间件无关的东西：</p><table tabindex="0"><thead><tr><th>还在 core 里的</th><th>已经搬走的</th></tr></thead><tbody><tr><td><code>GenericContainer</code>、<code>Network</code>、<code>Container</code>、<code>ContainerState</code></td><td><code>MySQLContainer</code> → <code>testcontainers-mysql</code></td></tr><tr><td><code>DockerComposeContainer</code>、<code>ComposeContainer</code></td><td><code>JdbcDatabaseContainer</code> → <code>testcontainers-jdbc</code></td></tr><tr><td><code>ImageNameSubstitutor</code>、<code>DockerImageName</code> 等工具类</td><td><code>@Testcontainers</code> / <code>@Container</code> → <code>testcontainers-junit-jupiter</code></td></tr></tbody></table><p>核实方式很直接——把 <code>testcontainers-2.0.5.jar</code> 拉下来列一遍类名，<code>JdbcDatabaseContainer</code>、<code>MySQLContainer</code>、<code>PostgreSQLContainer</code> 一个都搜不到：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testcontainers-2.0.5.jar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;JdbcDatabaseContainer|MySQLContainer&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 没有输出</span></span></code></pre></div><p>所以<strong>引了 core 不等于有 <code>MySQLContainer</code></strong>。缺 <code>testcontainers-mysql</code> 会在编译期直接报“找不到符号”，不会拖到运行期。</p><h3 id="变化二-坐标名加了前缀-和-1-x-相反" tabindex="-1">变化二：坐标名加了前缀（和 1.x 相反） <a class="header-anchor" href="#变化二-坐标名加了前缀-和-1-x-相反" aria-label="Permalink to &quot;变化二：坐标名加了前缀（和 1.x 相反）&quot;">​</a></h3><p>这一条最反直觉，因为它是<strong>反着改</strong>的：</p><table tabindex="0"><thead><tr><th>模块</th><th>1.x 坐标</th><th>2.0 坐标</th></tr></thead><tbody><tr><td>MySQL 容器</td><td><code>org.testcontainers:mysql</code>（1.21.4）</td><td><code>org.testcontainers:testcontainers-mysql</code>（2.0.5）</td></tr><tr><td>JUnit 5 支持</td><td><code>org.testcontainers:junit-jupiter</code>（1.21.4）</td><td><code>org.testcontainers:testcontainers-junit-jupiter</code>（2.0.5）</td></tr><tr><td>JDBC 基类</td><td><code>org.testcontainers:jdbc</code>（1.21.4）</td><td><code>org.testcontainers:testcontainers-jdbc</code>（2.0.5）</td></tr></tbody></table><p>注意两个 metadata 的版本线，它们是<strong>两条并行的线</strong>、互不覆盖：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>org.testcontainers:mysql                  → &lt;release&gt; 1.21.4</span></span>
<span class="line"><span>org.testcontainers:testcontainers-mysql    → &lt;release&gt; 2.0.5</span></span></code></pre></div><p>这意味着<strong>旧的 <code>org.testcontainers:mysql</code> 不会自动跳到 2.0</strong>。如果你的 <code>pom.xml</code> 里写的是老坐标，版本会一直停在 1.21.4，看起来“升级了 Boot 但 Testcontainers 没动”。</p><h3 id="变化三-包名从-containers-搬到了各自的技术栈下" tabindex="-1">变化三：包名从 <code>containers</code> 搬到了各自的技术栈下 <a class="header-anchor" href="#变化三-包名从-containers-搬到了各自的技术栈下" aria-label="Permalink to &quot;变化三：包名从 \`containers\` 搬到了各自的技术栈下&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类</th><th>1.x 包名</th><th>2.0 包名</th></tr></thead><tbody><tr><td><code>MySQLContainer</code></td><td><code>org.testcontainers.containers</code></td><td><code>org.testcontainers.mysql</code></td></tr><tr><td><code>JdbcDatabaseContainer</code></td><td><code>org.testcontainers.containers</code></td><td><code>org.testcontainers.containers</code>（未变，但在 <code>testcontainers-jdbc</code> 模块里）</td></tr><tr><td><code>@Testcontainers</code> / <code>@Container</code></td><td><code>org.testcontainers.junit.jupiter</code></td><td><code>org.testcontainers.junit.jupiter</code>（未变，但换了模块）</td></tr></tbody></table><p>跟 Boot 4 自己的做法一样：<strong>技术栈专属的类挪进技术栈命名空间</strong>。</p><p>这里有个细节要注意——<code>org.testcontainers.containers.MySQLContainer</code> <strong>在 2.0 里仍然存在</strong>，能 import、能编译，只是类的内部已经变成对新的 <code>org.testcontainers.mysql.MySQLContainer</code> 的包装。所以**“能编译过”不能作为“用的是新写法”的证据**。反编译对比一下两个包的类声明能看出区别：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新：public class org.testcontainers.mysql.MySQLContainer</span></span>
<span class="line"><span>        extends org.testcontainers.containers.JdbcDatabaseContainer&lt;org.testcontainers.mysql.MySQLContainer&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>旧：public class org.testcontainers.containers.MySQLContainer&lt;SELF extends ...MySQLContainer&lt;SELF&gt;&gt;</span></span>
<span class="line"><span>        extends org.testcontainers.containers.JdbcDatabaseContainer&lt;SELF&gt;</span></span></code></pre></div><h3 id="变化四-去掉了自引用的泛型参数" tabindex="-1">变化四：去掉了自引用的泛型参数 <a class="header-anchor" href="#变化四-去掉了自引用的泛型参数" aria-label="Permalink to &quot;变化四：去掉了自引用的泛型参数&quot;">​</a></h3><p>旧写法是 <code>MySQLContainer&lt;SELF extends MySQLContainer&lt;SELF&gt;&gt;</code> 这种自引用泛型，用来让链式调用返回子类型。2.0 把它去掉了，<code>MySQLContainer</code> 不再有类型参数：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 1.x 的写法</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MySQLContainer&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; mysql </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MySQLContainer&lt;&gt;(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mysql:8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.0 的写法，不需要钻石操作符</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MySQLContainer mysql </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MySQLContainer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mysql:8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="怎么快速判断一个坐标-包名到底改没改" tabindex="-1">怎么快速判断一个坐标/包名到底改没改 <a class="header-anchor" href="#怎么快速判断一个坐标-包名到底改没改" aria-label="Permalink to &quot;怎么快速判断一个坐标/包名到底改没改&quot;">​</a></h3><p>结合第 7 篇和第 8 篇用过的办法，这类“升级后编译不过”的问题都可以按下面的顺序查，比翻文档快：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 查坐标的最新版本线，看有没有并行的新旧两条</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://repo1.maven.org/maven2/org/testcontainers/mysql/maven-metadata.xml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 把 jar 拉下来，直接看到底有哪些类</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testcontainers-mysql-2.0.5.jar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\\.class&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 类名没变却报&quot;找不到包&quot;，基本就是包名迁移</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xxx.jar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 关键词</span></span></code></pre></div><hr>`,26)])])}const g=s(i,[["render",o]]);export{k as __pageData,g as default};
